  #region Enums
  /// <summary>
  /// Identifies whether a transcription was produced by an automatic
  /// speech-to-text system or by a human annotator.
  /// </summary>
  public enum TranscriptionType {
    /// <summary>
    /// Sentinel value when the source of the transcription was not specified.
    /// </summary>
    [pbr::OriginalName("TRANSCRIPTION_TYPE_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Automatic transcription produced by a speech-to-text system.
    /// </summary>
    [pbr::OriginalName("TRANSCRIPTION_TYPE_S2T")] S2T = 1,
    /// <summary>
    /// Manual transcription produced by a human annotator.
    /// </summary>
    [pbr::OriginalName("TRANSCRIPTION_TYPE_HUMAN")] Human = 2,
  }

  /// <summary>
  /// Effort level for reasoning models (e.g. o1, o3). Controls the trade-off
  /// between speed and quality.
  /// </summary>
  public enum ReasoningEffort {
    /// <summary>
    /// Unspecified reasoning effort.
    /// </summary>
    [pbr::OriginalName("REASONING_EFFORT_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Minimal reasoning effort.
    /// </summary>
    [pbr::OriginalName("REASONING_EFFORT_MINIMAL")] Minimal = 1,
    /// <summary>
    /// Low reasoning effort.
    /// </summary>
    [pbr::OriginalName("REASONING_EFFORT_LOW")] Low = 2,
    /// <summary>
    /// Medium reasoning effort.
    /// </summary>
    [pbr::OriginalName("REASONING_EFFORT_MEDIUM")] Medium = 3,
    /// <summary>
    /// High reasoning effort.
    /// </summary>
    [pbr::OriginalName("REASONING_EFFORT_HIGH")] High = 4,
  }

  /// <summary>
  /// Where a safety finding was located in the LLM call.
  /// </summary>
  public enum LlmSafetyLocation {
    /// <summary>
    /// Default / unset.
    /// </summary>
    [pbr::OriginalName("LLM_SAFETY_LOCATION_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// The finding was matched in the model input (prompt / user turn).
    /// </summary>
    [pbr::OriginalName("LLM_SAFETY_LOCATION_INPUT")] Input = 1,
    /// <summary>
    /// The finding was matched in the model output (completion).
    /// </summary>
    [pbr::OriginalName("LLM_SAFETY_LOCATION_OUTPUT")] Output = 2,
  }

  /// <summary>
  /// Lifecycle phase of an AI Team graph node, reported by &lt;code>LlmAgentNodeEvent&lt;/code>.
  /// </summary>
  public enum LlmAgentNodePhase {
    /// <summary>
    /// Not set.
    /// </summary>
    [pbr::OriginalName("LLM_AGENT_NODE_PHASE_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// The node started running.
    /// </summary>
    [pbr::OriginalName("LLM_AGENT_NODE_PHASE_STARTED")] Started = 1,
    /// <summary>
    /// The node finished without an error.
    /// </summary>
    [pbr::OriginalName("LLM_AGENT_NODE_PHASE_COMPLETED")] Completed = 2,
    /// <summary>
    /// The node raised an error.
    /// </summary>
    [pbr::OriginalName("LLM_AGENT_NODE_PHASE_FAILED")] Failed = 3,
  }

  /// <summary>
  /// Why a turn was interrupted.
  /// </summary>
  public enum TurnInterruptionReason {
    /// <summary>
    /// Not set.
    /// </summary>
    [pbr::OriginalName("TURN_INTERRUPTION_REASON_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// The user spoke over the answer and the interruption was confirmed as real.
    /// </summary>
    [pbr::OriginalName("TURN_INTERRUPTION_REASON_BARGE_IN")] BargeIn = 1,
    /// <summary>
    /// The user spoke again while the turn was still being generated, before any of its answer was played.
    /// </summary>
    [pbr::OriginalName("TURN_INTERRUPTION_REASON_CALLER_SPOKE_WHILE_THINKING")] CallerSpokeWhileThinking = 2,
    /// <summary>
    /// The call ended while the turn was being generated or played.
    /// </summary>
    [pbr::OriginalName("TURN_INTERRUPTION_REASON_CALL_ENDED")] CallEnded = 3,
    /// <summary>
    /// A filler of the turn was cut.
    /// </summary>
    [pbr::OriginalName("TURN_INTERRUPTION_REASON_FILLER_CUT")] FillerCut = 4,
    /// <summary>
    /// The user started speaking but no final transcript arrived in time, and the held answer was discarded.
    /// </summary>
    [pbr::OriginalName("TURN_INTERRUPTION_REASON_NO_FINAL_TIMEOUT")] NoFinalTimeout = 5,
    /// <summary>
    /// A human operator took the call over.
    /// </summary>
    [pbr::OriginalName("TURN_INTERRUPTION_REASON_OPERATOR_TAKEOVER")] OperatorTakeover = 6,
    /// <summary>
    /// A human operator muted the bot.
    /// </summary>
    [pbr::OriginalName("TURN_INTERRUPTION_REASON_BOT_MUTED")] BotMuted = 7,
  }

  /// <summary>
  /// What happens to background work (e.g. an asynchronous tool) the cancelled turn started.
  /// </summary>
  public enum BackgroundWorkPolicy {
    /// <summary>
    /// Keep it running; its result is delivered later as usual.
    /// </summary>
    [pbr::OriginalName("BACKGROUND_WORK_POLICY_KEEP")] Keep = 0,
    /// <summary>
    /// Cancel work that is still pending, unless the user already heard it acknowledged.
    /// </summary>
    [pbr::OriginalName("BACKGROUND_WORK_POLICY_CANCEL_PENDING")] CancelPending = 1,
  }

  /// <summary>
  /// How the heard text of a &lt;code>HeardReport&lt;/code> was determined.
  /// </summary>
  public enum HeardTextPrecision {
    /// <summary>
    /// Not set.
    /// </summary>
    [pbr::OriginalName("HEARD_TEXT_PRECISION_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Nothing of the answer was heard.
    /// </summary>
    [pbr::OriginalName("HEARD_TEXT_PRECISION_NONE_HEARD")] NoneHeard = 1,
    /// <summary>
    /// The whole answer was heard.
    /// </summary>
    [pbr::OriginalName("HEARD_TEXT_PRECISION_FULL")] Full = 2,
    /// <summary>
    /// The played share of the audio was estimated by the client from when it handed the audio to the player, not
